use std::{env,fs};use wasmc_csv_component as csv;use wasmc_data_core_component as core;use csv::wasmtime::{Engine,Store};use csv::wasmtime::component::{Component,Linker};
fn main(){let args:Vec<_>=env::args().collect();let engine=Engine::default();let mut store=Store::new(&engine,());let c=Component::new(&engine,fs::read(&args[1]).unwrap()).unwrap();let d=Component::new(&engine,fs::read(&args[2]).unwrap()).unwrap();let c=csv::Lib::instantiate(&mut store,&c,&Linker::new(&engine)).unwrap();let d=core::Lib::instantiate(&mut store,&d,&Linker::new(&engine)).unwrap();let parser=c.wasmc_csv_parser();let model=d.wasmc_data_core_model();for (n,b) in [(8,b'a'),(1048577,b'b'),(3145728,b'c'),(11,b'd')]{let mut data=vec![b;n];data.push(b'\n');let fields=[csv::wasmc::data_core::types::Field{name:"value".into(),data_type:csv::wasmc::data_core::types::DataType::Utf8,nullable:false}];let opts=csv::exports::wasmc::csv::parser::CsvOptions{has_header:false,validate_header:false,delimiter:b',',batch_rows:1};let mut parsed=parser.call_parse(&mut store,&data,&fields,opts).unwrap().unwrap();assert_eq!(parsed.len(),1);let mut batch=parsed.pop().unwrap();let value=match batch.columns.pop().unwrap(){csv::wasmc::data_core::types::Column::Utf8Column(v)=>v,_=>panic!("unexpected CSV output")};let batch=core::exports::wasmc::data_core::types::BatchSnapshot{rows:batch.rows,fields:vec![core::exports::wasmc::data_core::types::Field{name:"value".into(),data_type:core::exports::wasmc::data_core::types::DataType::Utf8,nullable:false}],columns:vec![core::exports::wasmc::data_core::types::Column::Utf8Column(value)]};assert_eq!(model.call_validate(&mut store,&batch).unwrap().unwrap(),1);let taken=model.call_take(&mut store,&batch,&[0]).unwrap().unwrap();match &taken.columns[0]{core::exports::wasmc::data_core::types::Column::Utf8Column(v)=>{let s=v[0].as_ref().unwrap();assert_eq!(s.len(),n);assert!(s.bytes().all(|x|x==b));},_=>panic!("unexpected data core output")};}println!("{{\"accepted\":true,\"pipeline\":\"csv.parse -> DataCore validate -> take\",\"largest_input\":3145728,\"same_instance_new_inputs\":true,\"component_sdk_value_mapping\":\"explicit Rust structural conversion\",\"formal_release\":false}}");}
